{
  "technical_and_design_decisions": [
    "Implement the library in Go using Hyperledger Fabric protobuf types and existing cryptographic and policy-validation primitives where possible.",
    "Represent the U2-U8 APIs with copied and adapted configuration structures rather than importing Viper or YAML processing; key material is supplied explicitly through function arguments or input structures.",
    "Generate protobuf messages deterministically and preserve Fabric configuration ordering and version semantics so results are semantically equivalent, and where practical byte/proto equivalent, to Fabric command-line tools.",
    "For U1, extend the transaction read-set representation to include the value observed for each read key, while retaining the key and version, and update validation to compare the endorsed value with the committing peer's world-state value.",
    "Preserve detached-signature semantics for U3 and U4: signing functions accept explicit identity and key material, and transaction assembly does not derive keys from configuration.",
    "Build configuration updates by cloning and transforming protobuf configuration trees, using Fabric-compatible version increments, read-set/write-set construction, policy metadata, and deterministic serialization.",
    "Use table-driven unit tests and integration-style tests against representative Fabric configuration fixtures and generated protobuf messages.",
    "Treat cryptographic verification, malformed protobuf handling, missing configuration paths, and inconsistent versions as explicit error cases rather than silently correcting inputs."
  ],
  "assumptions": [
    "The implementation is performed in an existing Fabric-compatible Go repository or fork where the relevant protobuf definitions, configuration types, signing interfaces, and validation code are available.",
    "The target Fabric release and protobuf schema are fixed before implementation; migration support across multiple incompatible Fabric releases is out of scope.",
    "U1 permits a coordinated protocol and protobuf change to the read-set representation and all participating peers are upgraded together; backward compatibility with unmodified peers is not required.",
    "The requested increment includes production code, unit tests, integration or fixture-based acceptance tests, API-level error handling, and concise developer documentation, but excludes deployment automation and operational rollout.",
    "Existing Fabric MSP, policy, protobuf, and cryptographic implementations may be reused when their behavior matches the required semantics; only the configuration-data ingestion layer is implemented independently of Viper and YAML.",
    "For U2 and U6, callers provide valid, already-parsed configuration data and cryptographic material in the agreed Go structures; parsing arbitrary configtx.yaml files and generating cryptographic material are out of scope.",
    "Acceptance comparisons allow semantically equivalent protobuf structures where Fabric tools may produce nonessential ordering or serialization differences, except where deterministic proto equality is explicitly required.",
    "The developer has access to representative integration-test profiles, MSP certificates, keys, channel configurations, and a local Fabric test environment; no external network access is required.",
    "The effort estimate is for one developer and represents work-hours, including implementation, review of local behavior, test execution, and defect correction, not elapsed calendar time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository and Fabric architecture analysis",
      "activity_description": "Inspect the target Fabric version, transaction protobufs, proposal response flow, endorsement processing, validation and commit paths, configuration APIs, signing utilities, and existing test conventions. Define interfaces and identify compatibility impacts before coding.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 read-set representation and propagation changes",
      "activity_description": "Modify the transaction read-set data model and serialization to carry the value observed during chaincode execution in addition to each key and version. Update chaincode execution, proposal response construction, peer-to-peer propagation, and related conversion code.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 validation and commit enforcement",
      "activity_description": "Update transaction validation to compare endorsed read values with the validating peer's current world-state values and invalidate transactions when values differ, while preserving normal version and MVCC checks and correct handling of absent keys.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 security and regression testing",
      "activity_description": "Add tests for tampered world state, tampered read values, changed versions, missing keys, multiple reads, valid transactions, mixed valid and invalid blocks, serialization round trips, and regression behavior for ordinary endorsement and commit flows.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A5",
      "activity_name": "Common configuration and protobuf utility layer",
      "activity_description": "Implement copied/adapted configuration structures, conversion helpers, deterministic protobuf handling, config-tree traversal, version management, policy helpers, and common validation/error utilities used by U2 and U5-U8.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 channel creation transaction generation",
      "activity_description": "Implement the channel specification API and generation of a proto-encoded genesis block, including channel group, orderer, application, consortium, capabilities, policies, organizations, and required headers. Match representative configtxgen output.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A7",
      "activity_name": "U6 organization ConfigGroup generation",
      "activity_description": "Implement generation of an organization ConfigGroup from explicit organization name, MSP identifiers, certificates, endpoints, policies, and related cryptographic material without reading MSP directories or configuration files.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "U7 ConfigUpdate computation",
      "activity_description": "Implement calculation of a ConfigUpdate from base and modified configuration transactions, including read and write sets, deletion detection, version checks, group traversal, and output semantics equivalent to configtxlator compute_update.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A9",
      "activity_name": "U5 max_message_count update generation",
      "activity_description": "Implement creation of an unsigned channel configuration update that changes the orderer batch max_message_count value, including correct channel identifiers, group versions, update envelope construction, and validation of supported input paths.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A10",
      "activity_name": "U8 consortium organization addition",
      "activity_description": "Implement creation of a system-channel configuration update that adds an existing organization definition to a named consortium, using the generated organization ConfigGroup and correct consortium and channel-group version updates without creating a new channel.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A11",
      "activity_name": "U3 detached ChannelUpdate signing",
      "activity_description": "Implement an API that accepts a ChannelUpdate transaction, explicit signing identity and key material, and signing parameters, then produces a Fabric-compatible detached signature without consulting configuration for key discovery.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A12",
      "activity_name": "U4 signed configuration update assembly",
      "activity_description": "Implement assembly of a complete signed channel configuration update from a ConfigUpdate and a collection of detached signatures, preserving signature order and creator information and producing an envelope accepted by Fabric validation and equivalent to sequential signtx operations.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A13",
      "activity_name": "Acceptance fixtures and cross-tool integration tests",
      "activity_description": "Create representative channel profiles, organizations, MSP material, base and modified configurations, and signed-update scenarios. Compare generated results with configtxgen, cryptogen, configtxlator, protolator, and signtx outputs using semantic and proto equality checks.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A14",
      "activity_name": "API documentation and examples",
      "activity_description": "Document public types, function contracts, explicit key-material requirements, error behavior, supported configuration paths, detached-signature usage, and examples for generating and assembling transactions.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A15",
      "activity_name": "Final integration, defect correction, and quality checks",
      "activity_description": "Run the complete test suite, investigate cross-component failures, correct serialization or compatibility defects, perform static analysis and formatting, and verify that all acceptance scenarios pass together.",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 572
  }
}

